const crypto = require('crypto');
const start = Date.now();

function doHeavyMath(id) {
  crypto.pbkdf2('pwd', 'salt', 100000, 512, 'sha512', () => {
    console.log(`Task ${id} finished in ${Date.now() - start}ms`);
  });
}

